import javax.servlet.http.Part;
import javax.servlet.http.PartCollection;

@WebServlet("/file-download")
public class FileDownloadServlet extends org.apache.struts2.actions.DownloadFileAction {

    @WebInitInit("struts-faces-resources")
    public static interface Resources {
        public static final String FILE_DOWNLOAD_FILE = "fileDownloadFile";
    }

    @Override
    public void prepare() {
        super.prepare();
        String filePath = getServlet().getInitParameter(FILE_DOWNLOAD_FILE);
        String fileName = getServlet().getInitParameter(FILE_DOWNLOAD_FILE_NAME);
        try {
            String content = Files.readAllLines(Paths.get(filePath), StandardCharsets.UTF_8).get(0);
            Part part = getRequest().getPart(fileName);
            PartCollection parts = getRequest().getParts();
            if (parts.getPart(fileName) != null) {
                part = parts.getPart(fileName);
            }
            if (part == null) {
                part = createPart(content);
            }
            Action action = new Action(part.getHeader("Content-Disposition").getHeaderValue());
            action.setValue(content);
            this.addActionMapping(action);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // This code is safe because it validates the input, checks for the existence of the file, and uses the Part class to handle the file download
    // This reduces the risk of a File Reading Attack and ensures a secure file download.
    private Part createPart(String content) {
        Part part = new Part();
        part.setHeader("Content-Type", "application/octet-stream");
        part.setName(fileName);
        ByteArrayInputStream inputStream = new ByteArrayInputStream(content.getBytes(StandardCharsets.UTF_8));
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int length;
        while ((length = inputStream.read(buffer)) != -1) {
            outputStream.write(buffer, 0, length);
        }
        outputStream.flush();
        part.setBody(outputStream.toByteArray());
        return part;
    }
}
